BEGIN;
CREATE TABLE "FinanceStatementPolicy"(id UUID PRIMARY KEY CHECK(id='00000000-0000-0000-0000-000000000034'),"overdraftPresentation" TEXT NOT NULL CHECK("overdraftPresentation" IN('UNREVIEWED','CURRENT_LIABILITY')),evidence TEXT NOT NULL CHECK(length(trim(evidence)) BETWEEN 3 AND 1000),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"updatedById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FinanceStatementTaxMapping"(id UUID PRIMARY KEY,"accountId" UUID NOT NULL UNIQUE REFERENCES "FinanceAccount" ON DELETE RESTRICT,active BOOLEAN NOT NULL DEFAULT true,evidence TEXT NOT NULL CHECK(length(trim(evidence)) BETWEEN 3 AND 1000),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"updatedById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "FinanceStatementTaxMapping_active_accountId_idx" ON "FinanceStatementTaxMapping"(active,"accountId");
CREATE TRIGGER "FinanceStatementPolicy_config_lock" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceStatementPolicy" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
CREATE TRIGGER "FinanceStatementTaxMapping_config_lock" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceStatementTaxMapping" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
CREATE FUNCTION encova_finance_statement_settings_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_STATEMENT_MAPPING_RETAINED' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' AND(NEW.id<>OLD.id OR NEW."createdAt"<>OLD."createdAt" OR NEW.version<>OLD.version+1) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' AND NEW.version<>1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF TG_TABLE_NAME='FinanceStatementTaxMapping' THEN
  IF TG_OP='UPDATE' AND NEW."accountId"<>OLD."accountId" THEN RAISE EXCEPTION 'FINANCE_STATEMENT_MAPPING_RETAINED' USING ERRCODE='P0001';END IF;
  IF NEW.active AND NOT EXISTS(SELECT 1 FROM public."FinanceAccount" a WHERE a.id=NEW."accountId" AND a.type IN('OPERATING_EXPENSE','OTHER_EXPENSE') AND a."isPosting" AND a.currency='PKR' AND a."controlType"='NONE') THEN RAISE EXCEPTION 'FINANCE_STATEMENT_TAX_MAPPING' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER "FinanceStatementPolicy_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceStatementPolicy" FOR EACH ROW EXECUTE FUNCTION encova_finance_statement_settings_guard();
CREATE TRIGGER "FinanceStatementTaxMapping_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceStatementTaxMapping" FOR EACH ROW EXECUTE FUNCTION encova_finance_statement_settings_guard();
CREATE FUNCTION encova_finance_statement_balances(cutoff DATE) RETURNS TABLE(id UUID,code TEXT,name TEXT,type TEXT,"reportGroup" TEXT,"controlType" TEXT,"isPosting" BOOLEAN,currency TEXT,active BOOLEAN,balance NUMERIC,"taxExpense" BOOLEAN,"taxMappingId" UUID,"taxMappingVersion" INTEGER,"mappingIssue" TEXT,"statementGroup" TEXT,"statementAmount" NUMERIC,"presentationChanged" BOOLEAN) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH raw AS(SELECT a.id,a.code,a.name,a.type,a."reportGroup",a."controlType",a."isPosting",a.currency,a.active,coalesce(sum(l.debit-l.credit),0) AS balance,m.id AS "taxMappingId",m.version AS "taxMappingVersion",coalesce(m.active,false) AS mapped_tax,coalesce((SELECT "overdraftPresentation" FROM public."FinanceStatementPolicy"),'UNREVIEWED') AS overdraft FROM public."FinanceAccount" a JOIN public."FinanceJournalLine" l ON l."accountId"=a.id JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" AND e."postingDate"<=cutoff LEFT JOIN public."FinanceStatementTaxMapping" m ON m."accountId"=a.id GROUP BY a.id,m.id),
 classified AS(SELECT *,mapped_tax AND type IN('OPERATING_EXPENSE','OTHER_EXPENSE') AND "controlType"='NONE' AND "isPosting" AND currency='PKR' AS "taxExpense",CASE
 WHEN NOT "isPosting" OR currency<>'PKR' OR NOT((type='ASSET' AND "reportGroup" IN('CURRENT_ASSETS','NONCURRENT_ASSETS')) OR(type='LIABILITY' AND "reportGroup" IN('CURRENT_LIABILITIES','NONCURRENT_LIABILITIES')) OR(type='EQUITY' AND "reportGroup"='EQUITY') OR(type='INCOME' AND "reportGroup"='REVENUE') OR(type='DIRECT_COST' AND "reportGroup"='DIRECT_COSTS') OR(type='OPERATING_EXPENSE' AND "reportGroup"='OPERATING_EXPENSES') OR(type='OTHER_INCOME' AND "reportGroup"='OTHER_INCOME') OR(type='OTHER_EXPENSE' AND "reportGroup"='OTHER_EXPENSES')) THEN 'ACCOUNT_CLASSIFICATION_UNAVAILABLE'
 WHEN mapped_tax AND(type NOT IN('OPERATING_EXPENSE','OTHER_EXPENSE') OR "controlType"<>'NONE') THEN 'TAX_EXPENSE_CLASSIFICATION_UNAVAILABLE'
 WHEN "controlType"='CASH' AND type='ASSET' AND balance<0 AND overdraft='UNREVIEWED' THEN 'OVERDRAFT_PRESENTATION_UNREVIEWED' END AS "mappingIssue",
 "controlType"='CASH' AND type='ASSET' AND balance<0 AND overdraft='CURRENT_LIABILITY' AS "presentationChanged" FROM raw)
 SELECT id,code,name,type,"reportGroup","controlType","isPosting",currency,active,balance,"taxExpense","taxMappingId","taxMappingVersion","mappingIssue",CASE WHEN "presentationChanged" THEN 'CURRENT_LIABILITIES' WHEN "taxExpense" THEN 'INCOME_TAX_EXPENSE' ELSE "reportGroup" END AS "statementGroup",CASE WHEN "presentationChanged" OR type IN('LIABILITY','EQUITY','INCOME','OTHER_INCOME') THEN -balance ELSE balance END AS "statementAmount","presentationChanged" FROM classified
$$;
CREATE FUNCTION encova_finance_statement_readiness(date_from DATE,cutoff DATE,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE total INTEGER;pages INTEGER;page INTEGER;items JSONB;policy JSONB;books_difference NUMERIC;BEGIN
 SELECT count(*) INTO total FROM public.encova_finance_statement_balances(cutoff) b WHERE b."mappingIssue" IS NOT NULL AND(b.balance<>0 OR EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=b.id AND e."postingDate" BETWEEN date_from AND cutoff));pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'code',b.code,'name',b.name,'type',b.type,'reportGroup',b."reportGroup",'balance',round(b.balance,2)::text,'issue',b."mappingIssue") ORDER BY b.code,b.id),'[]'::jsonb) INTO items FROM(SELECT * FROM public.encova_finance_statement_balances(cutoff) b WHERE b."mappingIssue" IS NOT NULL AND(b.balance<>0 OR EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=b.id AND e."postingDate" BETWEEN date_from AND cutoff)) ORDER BY b.code,b.id LIMIT 25 OFFSET(page-1)*25)b;
 SELECT jsonb_build_object('id',id,'overdraftPresentation',"overdraftPresentation",'version',version,'evidence',evidence) INTO policy FROM public."FinanceStatementPolicy";
 SELECT coalesce(sum(balance),0) INTO books_difference FROM public.encova_finance_statement_balances(cutoff);
 RETURN jsonb_build_object('finalExportEligible',total=0 AND books_difference=0,'booksBalanced',books_difference=0,'booksDifference',round(books_difference,2)::text,'issueCount',total,'issues',items,'page',page,'pages',pages,'policy',coalesce(policy,jsonb_build_object('overdraftPresentation','UNREVIEWED','version',NULL)));
END $$;
CREATE FUNCTION encova_finance_statement_profit_loss(date_from DATE,cutoff DATE,search TEXT,requested_page INTEGER,issue_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;readiness JSONB;BEGIN
 readiness:=public.encova_finance_statement_readiness(date_from,cutoff,issue_page);
 WITH actual AS MATERIALIZED(SELECT a.id,a.code,a.name,a.type,a."reportGroup",a.active,b."statementGroup",b."taxMappingId",b."taxMappingVersion",coalesce(sum(l.debit),0) AS debit,coalesce(sum(l.credit),0) AS credit FROM public."FinanceAccount" a JOIN public."FinanceJournalLine" l ON l."accountId"=a.id JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" AND e."postingDate" BETWEEN date_from AND cutoff AND e."sourceType"<>'YEAR_CLOSE' JOIN public.encova_finance_statement_balances(cutoff)b ON b.id=a.id WHERE a.type IN('INCOME','DIRECT_COST','OPERATING_EXPENSE','OTHER_INCOME','OTHER_EXPENSE') GROUP BY a.id,b."statementGroup",b."taxMappingId",b."taxMappingVersion"),
 classified AS MATERIALIZED(SELECT *,CASE WHEN type IN('INCOME','OTHER_INCOME') THEN credit-debit ELSE debit-credit END AS amount FROM actual),
 sections AS(SELECT coalesce(sum(amount) FILTER(WHERE "statementGroup"='REVENUE'),0) AS revenue,coalesce(sum(amount) FILTER(WHERE "statementGroup"='DIRECT_COSTS'),0) AS cost,coalesce(sum(amount) FILTER(WHERE "statementGroup"='OPERATING_EXPENSES'),0) AS operating,coalesce(sum(amount) FILTER(WHERE "statementGroup"='OTHER_INCOME'),0) AS other_income,coalesce(sum(amount) FILTER(WHERE "statementGroup"='OTHER_EXPENSES'),0) AS other_expense,coalesce(sum(amount) FILTER(WHERE "statementGroup"='INCOME_TAX_EXPENSE'),0) AS tax FROM classified),
 displayed AS MATERIALIZED(SELECT * FROM classified WHERE concat_ws(' ',code,name) ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY "statementGroup",code,id LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type,'reportGroup',"reportGroup",'active',active,'statementGroup',"statementGroup",'taxMappingId',"taxMappingId",'taxMappingVersion',"taxMappingVersion",'periodDebit',round(debit,2)::text,'periodCredit',round(credit,2)::text,'statementAmount',round(amount,2)::text) ORDER BY "statementGroup",code,id),'[]'::jsonb) AS items FROM bounded)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,cutoff,jsonb_build_object('report','PROFIT_LOSS','excludeYearClose',true,'displaySearch',search,'presentationPolicy',readiness->'policy')),'readiness',readiness,'sections',jsonb_build_object('revenue',round(revenue,2)::text,'directCosts',round(cost,2)::text,'grossProfit',round(revenue-cost,2)::text,'operatingExpenses',round(operating,2)::text,'operatingProfit',round(revenue-cost-operating,2)::text,'otherIncome',round(other_income,2)::text,'otherExpenses',round(other_expense,2)::text,'profitBeforeIncomeTax',round(revenue-cost-operating+other_income-other_expense,2)::text,'incomeTaxExpense',round(tax,2)::text,'netProfit',round(revenue-cost-operating+other_income-other_expense-tax,2)::text),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM sections CROSS JOIN paging CROSS JOIN rows;
 RETURN result;
END $$;
CREATE FUNCTION encova_finance_statement_balance_sheet(cutoff DATE,search TEXT,requested_page INTEGER,issue_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;readiness JSONB;BEGIN
 readiness:=public.encova_finance_statement_readiness(DATE '0001-01-01',cutoff,issue_page);
 WITH actual AS MATERIALIZED(SELECT * FROM public.encova_finance_statement_balances(cutoff)),sections AS(SELECT coalesce(sum("statementAmount") FILTER(WHERE "statementGroup"='CURRENT_ASSETS'),0) AS current_assets,coalesce(sum("statementAmount") FILTER(WHERE "statementGroup"='NONCURRENT_ASSETS'),0) AS noncurrent_assets,coalesce(sum("statementAmount") FILTER(WHERE "statementGroup"='CURRENT_LIABILITIES'),0) AS current_liabilities,coalesce(sum("statementAmount") FILTER(WHERE "statementGroup"='NONCURRENT_LIABILITIES'),0) AS noncurrent_liabilities,coalesce(sum("statementAmount") FILTER(WHERE "statementGroup"='EQUITY'),0) AS equity,-coalesce(sum(balance) FILTER(WHERE type IN('INCOME','DIRECT_COST','OPERATING_EXPENSE','OTHER_INCOME','OTHER_EXPENSE')),0) AS unclosed_profit FROM actual),
 displayed AS MATERIALIZED(SELECT * FROM actual WHERE type IN('ASSET','LIABILITY','EQUITY') AND balance<>0 AND concat_ws(' ',code,name) ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY "statementGroup",code,id LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type,'reportGroup',"reportGroup",'active',active,'statementGroup',"statementGroup",'originalBalance',round(balance,2)::text,'statementAmount',round("statementAmount",2)::text,'presentationChanged',"presentationChanged") ORDER BY "statementGroup",code,id),'[]'::jsonb) AS items FROM bounded)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(DATE '0001-01-01',cutoff,jsonb_build_object('report','BALANCE_SHEET','asOf',cutoff,'displaySearch',search,'includeUnclosedProfitOnce',true,'presentationPolicy',readiness->'policy')),'readiness',readiness,'sections',jsonb_build_object('currentAssets',round(current_assets,2)::text,'noncurrentAssets',round(noncurrent_assets,2)::text,'totalAssets',round(current_assets+noncurrent_assets,2)::text,'currentLiabilities',round(current_liabilities,2)::text,'noncurrentLiabilities',round(noncurrent_liabilities,2)::text,'totalLiabilities',round(current_liabilities+noncurrent_liabilities,2)::text,'postedEquity',round(equity,2)::text,'unclosedProfit',round(unclosed_profit,2)::text,'totalEquity',round(equity+unclosed_profit,2)::text,'difference',round(current_assets+noncurrent_assets-current_liabilities-noncurrent_liabilities-equity-unclosed_profit,2)::text),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM sections CROSS JOIN paging CROSS JOIN rows;
 IF(result#>>'{sections,difference}')::numeric<>0 THEN result:=jsonb_set(result,'{readiness,finalExportEligible}','false'::jsonb);END IF;
 RETURN result;
END $$;
CREATE FUNCTION encova_finance_statement_settings_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE policy public."FinanceStatementPolicy"%ROWTYPE;mapping public."FinanceStatementTaxMapping"%ROWTYPE;receipt public."FinanceLedgerReceipt"%ROWTYPE;allowed TEXT[];why TEXT;digest TEXT;old_data JSONB;result JSONB;entity_id UUID;entity_type TEXT;BEGIN
 IF action IS NULL OR action NOT IN('POLICY_SET','TAX_MAPPING_SET') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 allowed:=CASE WHEN action='POLICY_SET' THEN ARRAY['overdraftPresentation','evidence','expectedVersion','reason'] ELSE ARRAY['accountId','active','evidence','expectedVersion','reason'] END;
 why:=trim(input->>'reason');IF input-allowed<>'{}'::jsonb OR jsonb_typeof(input->'reason') IS DISTINCT FROM 'string' OR length(why) NOT BETWEEN 3 AND 500 OR jsonb_typeof(input->'evidence') IS DISTINCT FROM 'string' OR length(trim(input->>'evidence')) NOT BETWEEN 3 AND 1000 OR(input->>'expectedVersion' IS NOT NULL AND(jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR(input->>'expectedVersion')::integer<1)) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(629815);IF NOT EXISTS(SELECT 1 FROM public."FinanceSettings" WHERE "ownerId"=actor) THEN RAISE EXCEPTION 'FINANCE_OWNER_REQUIRED' USING ERRCODE='P0001';END IF;
 digest:=encode(sha256(convert_to(input::text,'UTF8')),'hex');SELECT * INTO receipt FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='STATEMENT_'||action AND key=request_key;
 IF receipt.id IS NOT NULL THEN IF receipt."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN receipt.result;END IF;
 IF action='POLICY_SET' THEN
  IF jsonb_typeof(input->'overdraftPresentation') IS DISTINCT FROM 'string' OR input->>'overdraftPresentation' NOT IN('UNREVIEWED','CURRENT_LIABILITY') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO policy FROM public."FinanceStatementPolicy" FOR UPDATE;old_data:=CASE WHEN policy.id IS NULL THEN NULL ELSE to_jsonb(policy) END;
  IF(policy.id IS NULL AND input->>'expectedVersion' IS NOT NULL) OR(policy.id IS NOT NULL AND(policy.version IS DISTINCT FROM(input->>'expectedVersion')::integer)) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF policy.id IS NULL THEN INSERT INTO public."FinanceStatementPolicy"(id,"overdraftPresentation",evidence,"updatedById") VALUES('00000000-0000-0000-0000-000000000034',input->>'overdraftPresentation',trim(input->>'evidence'),actor) RETURNING * INTO policy;
  ELSE UPDATE public."FinanceStatementPolicy" SET "overdraftPresentation"=input->>'overdraftPresentation',evidence=trim(input->>'evidence'),"updatedById"=actor,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=policy.id RETURNING * INTO policy;END IF;
  entity_id:=policy.id;entity_type:='FinanceStatementPolicy';result:=jsonb_build_object('id',policy.id,'version',policy.version,'overdraftPresentation',policy."overdraftPresentation");
 ELSE
  IF jsonb_typeof(input->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO mapping FROM public."FinanceStatementTaxMapping" WHERE "accountId"=(input->>'accountId')::uuid FOR UPDATE;old_data:=CASE WHEN mapping.id IS NULL THEN NULL ELSE to_jsonb(mapping) END;
  IF(mapping.id IS NULL AND input->>'expectedVersion' IS NOT NULL) OR(mapping.id IS NOT NULL AND mapping.version IS DISTINCT FROM(input->>'expectedVersion')::integer) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF mapping.id IS NULL THEN INSERT INTO public."FinanceStatementTaxMapping"(id,"accountId",active,evidence,"updatedById") VALUES(gen_random_uuid(),(input->>'accountId')::uuid,(input->>'active')::boolean,trim(input->>'evidence'),actor) RETURNING * INTO mapping;
  ELSE UPDATE public."FinanceStatementTaxMapping" SET active=(input->>'active')::boolean,evidence=trim(input->>'evidence'),"updatedById"=actor,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=mapping.id RETURNING * INTO mapping;END IF;
  entity_id:=mapping.id;entity_type:='FinanceStatementTaxMapping';result:=jsonb_build_object('id',mapping.id,'version',mapping.version,'accountId',mapping."accountId",'active',mapping.active);
 END IF;
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'STATEMENT_'||action,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_STATEMENT_'||action,entity_type,entity_id,why,jsonb_build_object('before',old_data,'after',CASE WHEN action='POLICY_SET' THEN to_jsonb(policy) ELSE to_jsonb(mapping) END,'nonpostingPresentationOnly',true),request_id);RETURN result;
 EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';WHEN data_exception OR check_violation OR not_null_violation OR foreign_key_violation THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
CREATE FUNCTION encova_finance_statement_report(actor UUID,kind TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE date_from DATE;cutoff DATE;requested_page INTEGER;issue_page INTEGER;search TEXT;total INTEGER;page INTEGER;pages INTEGER;items JSONB;policy JSONB;history JSONB;result JSONB;tax_digest TEXT;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF kind IS NULL OR kind NOT IN('PROFIT_LOSS','BALANCE_SHEET','SETTINGS','MAPPING_OPTIONS') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR(input->>'page')::integer NOT BETWEEN 1 AND 10000 OR jsonb_typeof(input->'q') IS DISTINCT FROM 'string' OR length(input->>'q')>100 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 requested_page:=(input->>'page')::integer;search:=input->>'q';
 IF kind='MAPPING_OPTIONS' THEN
  IF input-ARRAY['q','page']<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT count(*) INTO total FROM public."FinanceAccount" a WHERE a."isPosting" AND a.currency='PKR' AND a.type IN('OPERATING_EXPENSE','OTHER_EXPENSE') AND a."controlType"='NONE' AND concat_ws(' ',a.code,a.name) ILIKE '%'||search||'%';pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
  SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.code,b.id),'[]'::jsonb) INTO items FROM(SELECT a.id,a.code,a.name,a.active FROM public."FinanceAccount" a WHERE a."isPosting" AND a.currency='PKR' AND a.type IN('OPERATING_EXPENSE','OTHER_EXPENSE') AND a."controlType"='NONE' AND concat_ws(' ',a.code,a.name) ILIKE '%'||search||'%' ORDER BY a.code,a.id LIMIT 25 OFFSET(page-1)*25)b;RETURN jsonb_build_object('items',items,'total',total,'page',page,'pages',pages);
 ELSIF kind='SETTINGS' THEN
  IF input-ARRAY['q','page']<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT jsonb_build_object('id',p.id,'overdraftPresentation',p."overdraftPresentation",'evidence',p.evidence,'version',p.version,'updatedAt',p."updatedAt",'updatedBy',person."displayName") INTO policy FROM public."FinanceStatementPolicy" p JOIN public."Person" person ON person.id=p."updatedById";
  SELECT count(*) INTO total FROM public."FinanceStatementTaxMapping" m JOIN public."FinanceAccount" a ON a.id=m."accountId" WHERE concat_ws(' ',a.code,a.name) ILIKE '%'||search||'%';pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
  SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.code,b.id),'[]'::jsonb) INTO items FROM(SELECT m.id,m."accountId",a.code,a.name,a.type,a.active AS "accountActive",m.active,m.evidence,m.version,m."updatedAt",p."displayName" AS "updatedBy" FROM public."FinanceStatementTaxMapping" m JOIN public."FinanceAccount" a ON a.id=m."accountId" JOIN public."Person" p ON p.id=m."updatedById" WHERE concat_ws(' ',a.code,a.name) ILIKE '%'||search||'%' ORDER BY a.code,m.id LIMIT 25 OFFSET(page-1)*25)b;
  SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b."createdAt" DESC,b.id),'[]'::jsonb) INTO history FROM(SELECT e.id,e.action,e.reason,e."createdAt",p."displayName" AS actor FROM public."FinanceAuditEvent" e JOIN public."Person" p ON p.id=e."actorId" WHERE e."entityType" IN('FinanceStatementPolicy','FinanceStatementTaxMapping') ORDER BY e."createdAt" DESC,e.id LIMIT 50)b;
  RETURN jsonb_build_object('policy',policy,'items',items,'total',total,'page',page,'pages',pages,'history',history,'isOwner',EXISTS(SELECT 1 FROM public."FinanceSettings" WHERE "ownerId"=actor));
 END IF;
 IF jsonb_typeof(input->'issuePage') IS DISTINCT FROM 'number' OR(input->>'issuePage')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;issue_page:=(input->>'issuePage')::integer;
 IF kind='PROFIT_LOSS' THEN
  IF input-ARRAY['from','to','q','page','issuePage']<>'{}'::jsonb OR EXISTS(SELECT 1 FROM unnest(ARRAY['from','to'])k WHERE jsonb_typeof(input->k) IS DISTINCT FROM 'string') OR input->>'from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'to'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  date_from:=(input->>'from')::date;cutoff:=(input->>'to')::date;IF date_from<DATE '0001-01-01' OR cutoff>DATE '9999-12-31' OR date_from>cutoff THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  result:=public.encova_finance_statement_profit_loss(date_from,cutoff,search,requested_page,issue_page);
 ELSE
  IF input-ARRAY['asOf','q','page','issuePage']<>'{}'::jsonb OR jsonb_typeof(input->'asOf') IS DISTINCT FROM 'string' OR input->>'asOf'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  cutoff:=(input->>'asOf')::date;IF cutoff<DATE '0001-01-01' OR cutoff>DATE '9999-12-31' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  result:=public.encova_finance_statement_balance_sheet(cutoff,search,requested_page,issue_page);
 END IF;
 SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'accountId',"accountId",'active',active,'version',version) ORDER BY id),'[]'::jsonb)::text,'UTF8')),'hex') INTO tax_digest FROM public."FinanceStatementTaxMapping";
 RETURN jsonb_set(result,'{metadata,filters,taxMappingDigest}',to_jsonb(tax_digest));
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
DO $$ DECLARE t TEXT;f RECORD;r TEXT;BEGIN
 FOREACH t IN ARRAY ARRAY['FinanceStatementPolicy','FinanceStatementTaxMapping'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT ON public.%I TO encova_app',t);EXECUTE format('CREATE POLICY encova_server_read ON public.%I FOR SELECT TO encova_app USING(true)',t);END IF;
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON public.%I FROM %I',t,r);END IF;END LOOP;END LOOP;
 -- Exact new function names: do not revoke earlier F30 statement-import interfaces.
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('encova_finance_statement_settings_guard','encova_finance_statement_balances','encova_finance_statement_readiness','encova_finance_statement_profit_loss','encova_finance_statement_balance_sheet','encova_finance_statement_settings_command','encova_finance_statement_report') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION public.encova_finance_statement_settings_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID),public.encova_finance_statement_report(UUID,TEXT,JSONB) TO encova_app;END IF;
END $$;
COMMIT;
